// PrincipalVerdicts returns the full canonical principal verdict registry.
func PrincipalVerdicts() []PrincipalVerdict { return principalVerdicts }

// PrincipalVerdictByCanonical returns the verdict with the given canonical name.
func PrincipalVerdictByCanonical(name string) (PrincipalVerdict, bool) {
	for _, v := range principalVerdicts {
		if v.Canonical == name {
			return v, true
		}
	}
	return PrincipalVerdict{}, false
}
